{"source":"#include <stdio.h>

int main(int argc, char *argv[]) {
    int i,a[3],b[3];
    for(i=0;i<3;i++){
        scanf("%d%d",&a[i],&b[i]);
    }
    int ok=0;
    int x,y;
    for(x=0;x<2;x++){
        for(y=0;y<2;y++){
            int W = x? b[0]:a[0];
            int H = x? a[0]:b[0];
            int w1 = y? b[1]:a[1];
            int h1 = y? a[1]:b[1];
            int w2 = y? b[2]:a[2];
            int h2 = y? a[2]:b[2];
            if(w1<=W && h1<=H && w2<=W && h2<=H) ok=1;
            if(w1+w2<=W && h1<=H && h2<=H) ok=1;
            if(h1+h2<=H && w1<=W && w2<=W) ok=1;
            if(w1+h2<=W && h1<=H && w2<=W) ok=1;
            if(h1+w2<=H && w1<=W && h2<=H) ok=1;
        }
    }
    if(ok) printf("YES\n");
    else printf("NO\n");
    return 0;
}"}
